      billId: bill.id,
      billNumber: bill.number || bill.id,
      employeeName: bill.vendorName?.trim() || claim.submittedByName?.trim() || 'Unknown employee',
      submittedBy: claim.submittedByName?.trim() || '',
      date,
      state: claim.state,
      currency: bill.currency || input.homeCurrency || 'USD',
      amountCents: Number.isFinite(bill.amountCents) ? bill.amountCents : 0,
      receiptUrlRecorded,
      attachmentCount,
      evidenceStatus,
    }];
  }).sort@94:11

callee_expression:
z.object({
  deletionGraceDays: days('deletionGraceDays'),
  emailLogDays: z.union([z.literal(0), days('emailLogDays')]),
  errorLogDays: days('errorLogDays'),
  legalHold: z.boolean(),
}).strict

(() => {
  const standards = EU_VAT_RATES.filter(row => row.kind === 'standard');
  const seen = new Map<string, { country: string; countryName: string; standardRuleIds: string[] }>();
  for (const row of standards) {
    const entry = seen.get(row.country) || { country: row.country, countryName: row.countryName, standardRuleIds: [] };
    entry.standardRuleIds.push(`eu-${slug(row.country)}-standard-${slug(row.validFrom)}-${slug(String(row.rate))}`);
    seen.set(row.country, entry);
  }
  return [...seen.values()];
})

