})

callee_expression:
lines.map((line, i) => {
    const share = after[i] - before[i];
    const whole = share === amounts[i] && before[i] === 0;
    return {
      id: `${est.id}-${number}-${i}`,
      description: whole ? line.description || '' : `${line.description || 'Order line'} (${label})`,
      quantity: whole ? line.quantity || 1 : 1,
      rateCents: whole ? line.unitPriceCents || 0 : share,
      amountCents: share,
      // no account picked: posting uses the workspace's income account
      accountId: '',
      metadata: { orderLine: i },
    };
  }).filter

items.map(item => {
    const bought = item.moves.filter(m => m.kind === 'purchase' || m.kind === 'purchase-reversal');
    const quantity = round6(bought.reduce((s, m) => s + m.quantity, 0));
    const valueCents = bought.reduce((s, m) => s + m.valueCents, 0);
    return { itemId: item.itemId, itemName: item.itemName, quantity, valueCents, averageCents: quantity > 0 ? Math.round(valueCents / quantity) : 0 };
  }).filter

(text || '').normalize('NFC').toLowerCase()
    // Hebrew vocalization/cantillation and invisible direction controls aren't search terms.
    .replace

